// 代码中涉及的点均位于上述带状区域内
for( i = 0; i < numPointsInStrip; i++ )
    for( j = i + 1; j < numPointsInStrip; j++ )
        if( dist(pi, pj) < δ )
            δ = dist(pi, pj);

for( i = 0; i < numPointsInStrip; i++ )
    for( j = i + 1; j < numPointsInStrip; j++ )
        if( p\_i and p\_j's y-coordinates differ by more than δ )
            break;          // 转向下一个 p\_i.
        else
        if( dist(p\_i, p\_j) < δ )
            δ = dist(p\_i, p\_j);
